class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True
        n = len(s)
        first, last = {}, {}
        for i, c in enumerate(s):
            if c not in first:
                first[c] = i
            last[c] = i
        cand = []
        for l, c0 in first.items():
            r, seen = l, {c0}
            while True:
                nr = r
                for d in seen:
                    nr = max(nr, last[d])
                if nr == r:
                    break
                for i in range(r + 1, nr + 1):
                    seen.add(s[i])
                r = nr
            if min(first[d] for d in seen) == l and not (l == 0 and r == n - 1):
                cand.append((r, l))
        cand.sort()
        cnt, end = 0, -1
        for r, l in cand:
            if l > end:
                cnt += 1
                end = r
        return cnt >= k

