class Solution {
public:
    bool maxSubstringLength(string s, int k) {
        if (k == 0) return true;
        int n = s.size();
        int first[26], last[26]; fill(first, first+26, -1); fill(last, last+26, -1);
        for (int i = 0; i < n; i++) {
            int c = s[i]-'a';
            if (first[c] < 0) first[c] = i;
            last[c] = i;
        }
        vector<pair<int,int>> cand;
        for (int l = 0; l < n; l++) {
            int c0 = s[l]-'a';
            if (first[c0] != l) continue;
            int r = l; bool seen[26] = {false}; seen[c0] = true;
            while (true) {
                int nr = r;
                for (int d = 0; d < 26; d++) if (seen[d]) nr = max(nr, last[d]);
                if (nr == r) break;
                for (int i = r+1; i <= nr; i++) seen[s[i]-'a'] = true;
                r = nr;
            }
            bool ok = true;
            for (int d = 0; d < 26; d++) if (seen[d] && first[d] < l) ok = false;
            if (ok && !(l == 0 && r == n-1)) cand.push_back({r, l});
        }
        sort(cand.begin(), cand.end());
        int cnt = 0, end = -1;
        for (auto& [r, l] : cand) if (l > end) { cnt++; end = r; }
        return cnt >= k;
    }
};

