class Solution {
    public boolean maxSubstringLength(String s, int k) {
        if (k == 0) return true;
        int n = s.length();
        int[] first = new int[26], last = new int[26];
        Arrays.fill(first, -1);
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] < 0) first[c] = i;
            last[c] = i;
        }
        List<int[]> cand = new ArrayList<>();
        for (int l = 0; l < n; l++) {
            int c0 = s.charAt(l) - 'a';
            if (first[c0] != l) continue;
            int r = l; boolean[] seen = new boolean[26]; seen[c0] = true;
            while (true) {
                int nr = r;
                for (int d = 0; d < 26; d++) if (seen[d]) nr = Math.max(nr, last[d]);
                if (nr == r) break;
                for (int i = r + 1; i <= nr; i++) seen[s.charAt(i) - 'a'] = true;
                r = nr;
            }
            boolean ok = true;
            for (int d = 0; d < 26; d++) if (seen[d] && first[d] < l) ok = false;
            if (ok && !(l == 0 && r == n - 1)) cand.add(new int[]{r, l});
        }
        cand.sort((a, b) -> a[0] - b[0]);
        int cnt = 0, end = -1;
        for (int[] iv : cand) if (iv[1] > end) { cnt++; end = iv[0]; }
        return cnt >= k;
    }
}

