var maxSubstringLength = function(s, k) {
    if (k === 0) return true;
    const n = s.length, first = {}, last = {};
    for (let i = 0; i < n; i++) {
        const c = s[i];
        if (!(c in first)) first[c] = i;
        last[c] = i;
    }
    const cand = [];
    for (const lStr in first) {
        const l = +lStr;
        let r = l; const seen = new Set([s[l]]);
        while (true) {
            let nr = r;
            for (const d of seen) nr = Math.max(nr, last[d]);
            if (nr === r) break;
            for (let i = r + 1; i <= nr; i++) seen.add(s[i]);
            r = nr;
        }
        let ok = true;
        for (const d of seen) if (first[d] < l) ok = false;
        if (ok && !(l === 0 && r === n - 1)) cand.push([r, l]);
    }
    cand.sort((a, b) => a[0] - b[0]);
    let cnt = 0, end = -1;
    for (const [r, l] of cand) if (l > end) { cnt++; end = r; }
    return cnt >= k;
};
